// ❌ OLD: A plain field shared across threads. The writer thread sets
// stop=true, but there is NO happens-before edge, so the JIT may hoist
// the read out of the loop or the CPU cache may keep the stale value —
// the worker can spin forever.
public class StopFlag {
  static boolean stop = false; // ❌ OLD: no volatile, no happens-before

  public static void main(String[] args) throws Exception {
    Thread worker = new Thread(() -> {
      long i = 0;
      while (!stop) i++; // ❌ OLD: may read the cached false forever
    });
    worker.start();
    Thread.sleep(100);
    stop = true; // ❌ OLD: no guarantee the worker observes this
    worker.join();
  }
}

// ✅ NEW: volatile establishes happens-before: the main thread's write
// to stop happens-before the worker's read that observes it, so the
// JIT cannot hoist the read and the cache coherence protocol propagates
// the new value. The loop terminates reliably.
public class StopFlag {
  static volatile boolean stop = false; // ✅ NEW: visibility guaranteed

  public static void main(String[] args) throws Exception {
    Thread worker = new Thread(() -> {
      long i = 0;
      while (!stop) i++; // ✅ NEW: sees the volatile write
    });
    worker.start();
    Thread.sleep(100);
    stop = true; // ✅ NEW: volatile write
    worker.join();
  }
}

// Note: volatile is visibility-only. For compound updates (i++), use
// AtomicInteger or synchronized — volatile is NOT atomic.
